sys_script_client.script:
// Client Script: Filter u_outcome choices, auto-populate comments based on rule_category and auto-populate symphony chat room based on the values of outcome, collateral task type and managing location. 

function onLoad() {

    // Get rule_category and assignment_team values from form
    var ruleCategory;
    var team;

    // MSSCOLATRL-255
    var manLocation = ['hbeu otc', 'hbeu otc cash', 'hbeu repo', 'hbap hkh repo', 'hbap reg otc', 'hbap sgh otc', 'hbap sgh repo', 'hbap tky otc', 'hbap mnl otc', 'hbap sel otc', 'hbap bhk otc', 'hbap syd otc', 'hbap syd repo', 'hbau otc', 'hbap hbs otc', 'hbms otc', 'hbap mym otc', 'hase hkh otc', 'hase hkh repo', 'hbfr paris otc', 'hbfr paris repo'];

    try {
        ruleCategory = g_scratchpad.rule_category;
        team = g_form.getValue('u_assignment_team');

    } catch (e) {
        return;
    }
    if (!ruleCategory) return; // Exit if not set

    // Map for auto-populating comments field (journal)
    var commentsMap = {
        '5': 'Send settmoves to Treats or Settlement',
        '6': 'Send settmoves to Treats or Settlement',
        '9': 'Send Release Letter to Custodian'
    };

    // Set comments field if applicable
    try {
        if (g_scratchpad.assigned_to && g_scratchpad.assigned_to !== '') {
            g_form.setValue('comments', '');
        } else {
            var commentText = commentsMap[ruleCategory];
            if (commentText) {
                g_form.setValue('comments', commentText);
            }
        }
    } catch (e) {
        // Silent fail
    }



    // Map rule_category to allowed u_outcome choices
    var outcomeMap = {
        '1': ['No Action required - Auto Close'],
        '2': ['No Action required - Auto Close'],
        '2a': ['No Action required - Auto Close'],
        '3': ['No Action required - Auto Close'],
        '4': ['No Action required - Auto Close'],
        '4a': ['No Action required - Auto Close'],
        '5': ['Action required in Treats - Settmoves with user input',
            'No Action required ',
            'Action required',
            'Action required in SCP',
            'Action required in Treats - Settmoves',
            'Action required in Treats - Settmoves with user input'
        ],
        '6': ['Action required in Treats - Settmoves',
            'No Action required ',
            'Action required',
            'Action required in SCP',
            'Action required in Treats - Settmoves',
            'Action required in Treats - Settmoves with user input'
        ],
        '7': ['Action required',
            'No Action required ',
            'Action required',
            'Action required in SCP',
            'Action required in Treats - Settmoves',
            'Action required in Treats - Settmoves with user input'
        ],
        '8': ['Action required - Validate in ASM',
            'No Action required',
            'Action required',
            'Action required in SCP',
            'Action required in Treats - Settmoves',
            'Action required in Treats - Settmoves with user input',
            'Action required - Validate in ASM',
            'Action required - Send 3rdparty Release Letter',
            'Action required in Martini'
        ],
        '9': ['Action required - 3rdparty Release Letter',
            'No Action required',
            'Action required',
            'Action required in SCP',
            'Action required in Treats - Settmoves',
            'Action required in Treats - Settmoves with user input',
            'Action required - Validate in ASM',
            'Action required - Send 3rdparty Release Letter',
            'Action required in Martini'
        ],
        '10_margin': [
            'No Action required',
            'Action required',
            'Action required in SCP',
            'Action required in Treats - Settmoves',
            'Action required in Treats - Settmoves with user input',
            'Action required - Validate in ASM',
            'Action required - Send 3rdparty Release Letter',
            'Action required in Martini'
        ],
        '10_interest': [
            'No Action required',
            'Action required',
            'Action required in SCP',
            'Action required in Treats - Settmoves',
            'Action required in Treats - Settmoves with user input'
        ]
    };

    // Get allowed choices for u_outcome
    var allowedChoices;
    try {
        allowedChoices = outcomeMap[ruleCategory];
        if (g_form.getValue('managing_location').toLowerCase() == 'hbus otc' && team == 'collateral_margin') {
            allowedChoices.push('Action required in Impact');
        }

        // MSSCOLATRL-255

        if ((g_form.getValue('managing_location').toLowerCase() == 'hbfr paris otc' || g_form.getValue('managing_location').toLowerCase() == 'hbfr paris repo') && (team == 'collateral_margin' || team == 'collateral_interest')) {
            allowedChoices.push('Action required in GPS');
        }


        // MSSCOLATRL-255
        if (manLocation.includes(g_form.getValue('managing_location').toLowerCase()) && team == 'collateral_margin') {

            if (g_form.getValue('managing_location').toLowerCase() == 'hbeu otc' || g_form.getValue('managing_location').toLowerCase() == 'hbeu otc cash' || g_form.getValue('managing_location').toLowerCase() == 'hbeu repo') {

                allowedChoices.push('Action required in Martini - Cancel & Amend');
                allowedChoices.push('Action required in Martini - Unsettle & Amend/Cancel US/EM/AP');
                allowedChoices.push('Action required in Martini - Unsettle & Amend/Cancel EU');
                allowedChoices.push('Action required in Martini - Unsettle & Amend/Cancel GB');
                allowedChoices.push('Action required in Martini - Book/Amend/Cancel');

            }

            if (!(g_form.getValue('managing_location').toLowerCase() == 'hbfr paris otc' || g_form.getValue('managing_location').toLowerCase() == 'hbfr paris repo')) {

                allowedChoices.push('Action required in Martini - Book/Amend/Cancel');

            }

            allowedChoices.push('Action required in Martini - Unsettle IT');
        }

        if (!Array.isArray(allowedChoices)) allowedChoices = [];
    } catch (e) {
        allowedChoices = [];
    }

    // Clear and repopulate u_outcome choices
    try {
        g_form.clearOptions('u_outcome');
        allowedChoices.forEach(function(choice) {
            g_form.addOption('u_outcome', choice, choice);
        });
    } catch (e) {
        // Silent fail
    }

    // Set default outcome for specific categories or scratchpad
    try {
        var defaultOutcome;
        var defaultOutcomeMap = {
            '5': 'Action required in Treats - Settmoves with user input',
            '6': 'Action required in Treats - Settmoves',
            '7': 'Action required',
            '8': 'Action required - Validate in ASM',
            '9': 'Action required - 3rdparty Release Letter',
            '10_margin': 'Action required',
            '10_interest': 'Action required'
        };

        if (g_scratchpad.assigned_to && g_scratchpad.assigned_to !== '' && allowedChoices.includes(g_scratchpad.u_outcome)) {
            defaultOutcome = g_scratchpad.u_outcome;
        } else {
            defaultOutcome = defaultOutcomeMap[ruleCategory];
        }

        if (defaultOutcome && allowedChoices.includes(defaultOutcome)) {
            g_form.setValue('u_outcome', defaultOutcome);
        } else if (allowedChoices.length > 0) {
            g_form.setValue('u_outcome', allowedChoices[0]);
        }

        // if (!(g_scratchpad.collateral_task_type == 'Base Task')) {
        //     g_form.setReadOnly('u_outcome', true);
        // }
    } catch (e) {
        // Silent fail
    }

    //MSSCOLATRL-161: Making fields readonly based on the Collateral Task Type
    var collateralTaskType = g_scratchpad.collateral_task_type;
    switch (collateralTaskType) {
        case "Base Task":
            if (g_form.getValue('state') == 3) {
                var baseTaskFields = g_form.getEditableFields();
                for (var i = 0; i < baseTaskFields.length; i++) {
                    g_form.setReadOnly(baseTaskFields[i], true);
                }
            }
            break;

        case "Symphony API Task 1":
        case "Symphony API Task 2":
            var symphonyAPITaskFields = g_form.getEditableFields();
            for (var x = 0; x < symphonyAPITaskFields.length; x++) {
                g_form.setReadOnly(symphonyAPITaskFields[x], true);
            }
            break;

        case "Second Symphony Task":
            g_form.setReadOnly('u_outcome', true);
            if (g_form.getValue('state') == 3) {
                var secondSymphonyTaskFields = g_form.getEditableFields();
                for (var j = 0; j < secondSymphonyTaskFields.length; j++) {
                    g_form.setReadOnly(secondSymphonyTaskFields[j], true);
                }
            }
            break;

        case "Symphony Manual Task":
            g_form.setValue('u_outcome', "Action required in Martini");
            g_form.setReadOnly('u_outcome', true);
            if (g_form.getValue('state') == 1 || g_form.getValue('state') == 2) {
                g_modal.alert("ALERT: Symphony Integration Failed. Please use this manual task to further process the exception");
            }
            // alert(g_scratchpad.u_outcome);
            if (g_scratchpad.u_outcome == "Action required in Martini") {
                g_form.setValue('comments', '');

            } else if (g_scratchpad.u_outcome == "Action required in Martini - Cancel & Amend" || g_scratchpad.u_outcome == "Action required in Martini - Book/Amend/Cancel") {
                g_form.setValue('comments', "Please commit - \n\n" + g_scratchpad.u_martini_reference_1 + "\n\n" + g_scratchpad.u_martini_reference_2);
            } else {
                g_form.setValue('comments', "Please unsettle - \n\n" + g_scratchpad.u_martini_reference_1 + "\n\n" + g_scratchpad.u_martini_reference_2);
            }
            break;
    }

}
